const search=document.querySelector('input[type=search]');if(search){let filter='all';const rows=[...document.querySelectorAll('.incident')],buttons=[...document.querySelectorAll('[data-filter]')];function update(){const q=search.value.trim().toLocaleLowerCase('uk');let count=0;for(const row of rows){row.hidden=!((filter==='all'||(filter==='history'?row.dataset.kind==='history':row.dataset.category===filter))&&row.dataset.search.toLocaleLowerCase('uk').includes(q));if(!row.hidden)count++}buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));document.querySelector('.empty').hidden=count>0;document.querySelector('#result-count').textContent=`${count} із ${rows.length} розборів`}buttons.forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;update()}));search.addEventListener('input',update)}
